/* ------------------------------------------------------------------ */
/*  One Euro pose filter (low jitter at rest, no lag while moving)     */
/* ------------------------------------------------------------------ */

const euroAlpha = (cutoff, dt) => 1 / (1 + 1 / (2 * Math.PI * cutoff) / dt);

class OneEuroVector {
  constructor(dim, minCutoff = 1, beta = 0, dCutoff = 1) {
    this.dim = dim;
    this.minCutoff = minCutoff;
    this.beta = beta;
    this.dCutoff = dCutoff;
    this.x = new Float64Array(dim);
    this.dx = new Float64Array(dim);
    this.t = -1;
  }

  reset() {
    this.t = -1;
  }

  /** Filters `v` in place. `t` in seconds. */
  filter(v, t) {
    if (this.t < 0) {
      for (let i = 0; i < this.dim; i++) {
        this.x[i] = v[i];
        this.dx[i] = 0;
      }
      this.t = t;
      return;
    }
    const dt = Math.min(Math.max(t - this.t, 1e-3), 0.5);
    this.t = t;
    const aD = euroAlpha(this.dCutoff, dt);
    let speed = 0;
    for (let i = 0; i < this.dim; i++) {
      const d = (v[i] - this.x[i]) / dt;
      this.dx[i] = aD * d + (1 - aD) * this.dx[i];
      speed += this.dx[i] * this.dx[i];
    }
    const a = euroAlpha(this.minCutoff + this.beta * Math.sqrt(speed), dt);
    for (let i = 0; i < this.dim; i++) {
      this.x[i] = a * v[i] + (1 - a) * this.x[i];
      v[i] = this.x[i];
    }
  }
}

const SMOOTHING_PRESETS = {
  low: { posMinCutoff: 2.2, posBeta: 1.6, rotMinCutoff: 2.2, rotBeta: 30 },
  medium: { posMinCutoff: 1.0, posBeta: 0.9, rotMinCutoff: 1.0, rotBeta: 20 },
  high: { posMinCutoff: 0.45, posBeta: 0.45, rotMinCutoff: 0.45, rotBeta: 10 },
};

class PoseFilter {
  constructor(params) {
    this.pos = new OneEuroVector(3, params.posMinCutoff, params.posBeta);
    this.rot = new OneEuroVector(4, params.rotMinCutoff, params.rotBeta);
    this.scl = new OneEuroVector(1, Math.min(params.posMinCutoff, 1), 0);
    this.p = new THREE.Vector3();
    this.q = new THREE.Quaternion();
    this.s = new THREE.Vector3();
    this.prevQ = new THREE.Quaternion();
    this.hasPrev = false;
    this.b3 = [0, 0, 0];
    this.b4 = [0, 0, 0, 1];
    this.b1 = [1];
  }

  reset() {
    this.pos.reset();
    this.rot.reset();
    this.scl.reset();
    this.hasPrev = false;
  }

  apply(input, t, out) {
    input.decompose(this.p, this.q, this.s);
    // Keep quaternions in one hemisphere so component-wise filtering is valid.
    if (this.hasPrev && this.q.dot(this.prevQ) < 0) {
      this.q.set(-this.q.x, -this.q.y, -this.q.z, -this.q.w);
    }
    const { b3, b4, b1 } = this;
    b3[0] = this.p.x;
    b3[1] = this.p.y;
    b3[2] = this.p.z;
    this.pos.filter(b3, t);
    this.p.set(b3[0], b3[1], b3[2]);

    b4[0] = this.q.x;
    b4[1] = this.q.y;
    b4[2] = this.q.z;
    b4[3] = this.q.w;
    this.rot.filter(b4, t);
    this.q.set(b4[0], b4[1], b4[2], b4[3]).normalize();
    this.prevQ.copy(this.q);
    this.hasPrev = true;

    b1[0] = (this.s.x + this.s.y + this.s.z) / 3;
    this.scl.filter(b1, t);
    this.s.setScalar(b1[0]);
    return out.compose(this.p, this.q, this.s);
  }
}

/* ------------------------------------------------------------------ */
/*  Live metric 3D face (camera space, cm)                             */
/* ------------------------------------------------------------------ */

const LANDMARK_COUNT = 478;
const TAN_HALF_FOV = Math.tan(THREE.MathUtils.degToRad(FOV_Y_DEG) / 2);
const CANONICAL_CENTROID = (() => {
  const c = new THREE.Vector3();
  for (let i = 0; i < CANONICAL_VERTEX_COUNT; i++) {
    c.x += CANONICAL_POSITIONS[i * 3];
    c.y += CANONICAL_POSITIONS[i * 3 + 1];
    c.z += CANONICAL_POSITIONS[i * 3 + 2];
  }
  return c.divideScalar(CANONICAL_VERTEX_COUNT);
})();

/**
 * The pose matrix fixes the head's depth/scale; each landmark's normalised z
 * supplies the user's own relief. Every point lands exactly on its 2D pixel.
 */
class FaceReconstruction {
  constructor() {
    this.camera = new Float32Array(LANDMARK_COUNT * 3);
    this.pixels = new Float32Array(LANDMARK_COUNT * 2);
    this.matrix = new THREE.Matrix4();
    this.inverse = new THREE.Matrix4();
    this.width = 1;
    this.height = 1;
    this.focalPx = 1;
    this.v = new THREE.Vector3();
  }

  update(lms, matrix, width, height) {
    this.matrix.copy(matrix);
    this.inverse.copy(matrix).invert();
    this.width = width;
    this.height = height;
    const f = height / 2 / TAN_HALF_FOV;
    this.focalPx = f;

    const dRef = Math.max(-this.v.copy(CANONICAL_CENTROID).applyMatrix4(matrix).z, 5);
    let zMean = 0;
    for (let i = 0; i < CANONICAL_VERTEX_COUNT; i++) zMean += lms[i].z;
    zMean /= CANONICAL_VERTEX_COUNT;
    const zScale = (width * dRef) / f;

    const n = Math.min(lms.length, LANDMARK_COUNT);
    for (let i = 0; i < n; i++) {
      const l = lms[i];
      const u = l.x * width;
      const v = l.y * height;
      this.pixels[i * 2] = u;
      this.pixels[i * 2 + 1] = v;
      this.setFromPixel(i, u, v, Math.max(dRef + (l.z - zMean) * zScale, 5));
    }
    if (n >= LANDMARK_COUNT) {
      // Iris points: use the depth of their eye's lid contour.
      const dR = this.meanDepth(RIGHT_EYE_CONTOUR);
      const dL = this.meanDepth(LEFT_EYE_CONTOUR);
      for (let i = 468; i < 473; i++) this.setFromPixel(i, this.pixels[i * 2], this.pixels[i * 2 + 1], dR);
      for (let i = 473; i < 478; i++) this.setFromPixel(i, this.pixels[i * 2], this.pixels[i * 2 + 1], dL);
    }
  }

  setFromPixel(i, u, v, depth) {
    const f = this.focalPx;
    this.camera[i * 3] = ((u - this.width / 2) * depth) / f;
    this.camera[i * 3 + 1] = (-(v - this.height / 2) * depth) / f;
    this.camera[i * 3 + 2] = -depth;
  }

  meanDepth(ids) {
    let d = 0;
    for (const i of ids) d -= this.camera[i * 3 + 2];
    return d / ids.length;
  }

  getCanonical(i, out) {
    return out.fromArray(this.camera, i * 3).applyMatrix4(this.inverse);
  }

  pixelDistance(a, b) {
    return Math.hypot(
      this.pixels[a * 2] - this.pixels[b * 2],
      this.pixels[a * 2 + 1] - this.pixels[b * 2 + 1],
    );
  }
}

/* ------------------------------------------------------------------ */
/*  Per-user calibration (iris scale, pupils, nose, ears)              */
/* ------------------------------------------------------------------ */

const NOSE_N = NOSE_MIDLINE.length;
const F_PUPIL_R = 0;
const F_PUPIL_L = 3;
const F_EYE_Z = 6;
const F_NOSE_Y = 7;
const F_NOSE_Z = F_NOSE_Y + NOSE_N;
const F_EAR_R = F_NOSE_Z + NOSE_N;
const F_EAR_L = F_EAR_R + 3;
const F_IRIS = F_EAR_L + 3;
const FIELDS = F_IRIS + 1;
const CAL_WINDOW = 60;
const FULL_IRIS_SAMPLES = 30;
const MAX_FACING_ANGLE = THREE.MathUtils.degToRad(20);
const MIN_EYE_OPENNESS = 0.16;
const MIN_IRIS_PX = 7;

const canonicalPoint = (i, out = new THREE.Vector3()) => out.fromArray(CANONICAL_POSITIONS, i * 3);

const meanCanonical = (ids) => {
  const v = new THREE.Vector3();
  const t = new THREE.Vector3();
  for (const i of ids) v.add(canonicalPoint(i, t));
  return v.divideScalar(ids.length);
};

const defaultRecord = () => {
  const r = new Float32Array(FIELDS);
  meanCanonical(RIGHT_EYE_CONTOUR).toArray(r, F_PUPIL_R);
  meanCanonical(LEFT_EYE_CONTOUR).toArray(r, F_PUPIL_L);
  r[F_EYE_Z] = meanCanonical(EYE_CONTOURS).z;
  NOSE_MIDLINE.forEach((id, k) => {
    r[F_NOSE_Y + k] = CANONICAL_POSITIONS[id * 3 + 1];
    r[F_NOSE_Z + k] = CANONICAL_POSITIONS[id * 3 + 2];
  });
  canonicalPoint(LM.rightEarFront).toArray(r, F_EAR_R);
  canonicalPoint(LM.leftEarFront).toArray(r, F_EAR_L);
  r[F_IRIS] = IRIS_DIAMETER_CM;
  return r;
};

/**
 * MediaPipe normalises every face to an average size, so `profile.scale`
 * (real cm per canonical cm, measured from the iris) is what turns a
 * real-size frame into a true-to-life fit. Medians over a sliding window.
 */
class FaceCalibrator {
  constructor() {
    this.defaults = defaultRecord();
    this.ring = new Float32Array(CAL_WINDOW * FIELDS);
    this.column = new Float32Array(CAL_WINDOW);
    this.median = new Float32Array(FIELDS);
    this.count = 0;
    this.head = 0;
    this.sinceRebuild = 0;
    this.manualPdMm = null;
    this.v = new THREE.Vector3();
    this.w = new THREE.Vector3();
    this.profile = {
      pupilR: new THREE.Vector3(),
      pupilL: new THREE.Vector3(),
      eyeZ: 0,
      noseY: new Float32Array(NOSE_N),
      noseZ: new Float32Array(NOSE_N),
      earFrontR: new THREE.Vector3(),
      earFrontL: new THREE.Vector3(),
      earR: new THREE.Vector3(),
      earL: new THREE.Vector3(),
      faceWidth: 0,
      scale: 1,
      progress: 0,
      source: "default",
    };
    this.reset();
  }

  reset() {
    this.count = 0;
    this.head = 0;
    this.median.set(this.defaults);
    this.rebuild(0);
  }

  setManualPd(pdMm) {
    this.manualPdMm = pdMm && pdMm > 40 && pdMm < 85 ? pdMm : null;
    this.rebuild(this.irisCount());
  }

  addFrame(recon) {
    if (!this.isGoodView(recon)) return false;
    const rec = this.ring.subarray(this.head * FIELDS, (this.head + 1) * FIELDS);
    const v = this.v;
    recon.getCanonical(LM.rightIrisCenter, v).toArray(rec, F_PUPIL_R);
    recon.getCanonical(LM.leftIrisCenter, v).toArray(rec, F_PUPIL_L);
    let eyeZ = 0;
    for (const i of EYE_CONTOURS) eyeZ += recon.getCanonical(i, v).z;
    rec[F_EYE_Z] = eyeZ / EYE_CONTOURS.length;
    NOSE_MIDLINE.forEach((id, k) => {
      recon.getCanonical(id, v);
      rec[F_NOSE_Y + k] = v.y;
      rec[F_NOSE_Z + k] = v.z;
    });
    recon.getCanonical(LM.rightEarFront, v).toArray(rec, F_EAR_R);
    recon.getCanonical(LM.leftEarFront, v).toArray(rec, F_EAR_L);
    rec[F_IRIS] = this.measureIris(recon);

    this.head = (this.head + 1) % CAL_WINDOW;
    this.count = Math.min(this.count + 1, CAL_WINDOW);
    if (this.count < CAL_WINDOW || ++this.sinceRebuild >= 4) {
      this.sinceRebuild = 0;
      this.computeMedians();
      this.rebuild(this.irisCount());
    }
    return true;
  }

  // Face shape is only measured from (near-)frontal views.
  isGoodView(recon) {
    const e = recon.matrix.elements;
    const fwd = this.v.set(e[8], e[9], e[10]).normalize();
    const toCam = this.w.set(-e[12], -e[13], -e[14]).normalize();
    return fwd.dot(toCam) >= Math.cos(MAX_FACING_ANGLE);
  }

  // Iris diameter in canonical cm; NaN while blinking or when too small to trust.
  measureIris(recon) {
    const openR =
      recon.pixelDistance(LM.rightEyeUpper, LM.rightEyeLower) /
      Math.max(recon.pixelDistance(LM.rightEyeOuter, LM.rightEyeInner), 1);
    const openL =
      recon.pixelDistance(LM.leftEyeUpper, LM.leftEyeLower) /
      Math.max(recon.pixelDistance(LM.leftEyeOuter, LM.leftEyeInner), 1);
    if (openR < MIN_EYE_OPENNESS || openL < MIN_EYE_OPENNESS) return NaN;
    const dR = this.irisPx(recon, RIGHT_IRIS_RING, LM.rightEyeOuter, LM.rightEyeInner);
    const dL = this.irisPx(recon, LEFT_IRIS_RING, LM.leftEyeOuter, LM.leftEyeInner);
    if (Math.min(dR, dL) < MIN_IRIS_PX) return NaN;
    const depth = (recon.meanDepth(RIGHT_EYE_CONTOUR) + recon.meanDepth(LEFT_EYE_CONTOUR)) / 2;
    return (((dR + dL) / 2) * depth) / recon.focalPx;
  }

  irisPx(recon, ring, outer, inner) {
    const p = recon.pixels;
    let ex = p[inner * 2] - p[outer * 2];
    let ey = p[inner * 2 + 1] - p[outer * 2 + 1];
    const el = Math.hypot(ex, ey) || 1;
    ex /= el;
    ey /= el;
    let best = 0;
    let bestAlign = -1;
    for (let k = 0; k < 2; k++) {
      const a = ring[k];
      const b = ring[k + 2];
      const dx = p[a * 2] - p[b * 2];
      const dy = p[a * 2 + 1] - p[b * 2 + 1];
      const len = Math.hypot(dx, dy);
      const align = Math.abs((dx * ex + dy * ey) / (len || 1));
      if (align > bestAlign) {
        bestAlign = align;
        best = len;
      }
    }
    return best;
  }

  irisCount() {
    let n = 0;
    for (let s = 0; s < this.count; s++) if (!Number.isNaN(this.ring[s * FIELDS + F_IRIS])) n++;
    return n;
  }

  computeMedians() {
    for (let f = 0; f < FIELDS; f++) {
      let n = 0;
      for (let s = 0; s < this.count; s++) {
        const val = this.ring[s * FIELDS + f];
        if (!Number.isNaN(val)) this.column[n++] = val;
      }
      if (n === 0) {
        this.median[f] = this.defaults[f];
        continue;
      }
      const col = this.column.subarray(0, n).sort();
      this.median[f] = n % 2 ? col[(n - 1) >> 1] : (col[n / 2 - 1] + col[n / 2]) / 2;
    }
  }

  rebuild(irisSamples) {
    const m = this.median;
    const p = this.profile;
    p.pupilR.fromArray(m, F_PUPIL_R);
    p.pupilL.fromArray(m, F_PUPIL_L);
    p.eyeZ = m[F_EYE_Z];
    for (let k = 0; k < NOSE_N; k++) {
      p.noseY[k] = m[F_NOSE_Y + k];
      p.noseZ[k] = m[F_NOSE_Z + k];
    }
    p.earFrontR.fromArray(m, F_EAR_R);
    p.earFrontL.fromArray(m, F_EAR_L);
    const o = EAR_ROOT_OFFSET;
    p.earR.set(p.earFrontR.x - o.out, p.earFrontR.y + o.up, p.earFrontR.z - o.back);
    p.earL.set(p.earFrontL.x + o.out, p.earFrontL.y + o.up, p.earFrontL.z - o.back);
    p.faceWidth = p.earFrontL.x - p.earFrontR.x;

    const ipdCanon = Math.max(p.pupilR.distanceTo(p.pupilL), 3);
    if (this.manualPdMm) {
      p.scale = this.manualPdMm / 10 / ipdCanon;
      p.source = "manual";
      p.progress = 1;
      return;
    }
    if (irisSamples >= 5) {
      const measured = clamp(IRIS_DIAMETER_CM / m[F_IRIS], 0.8, 1.25);
      const w = Math.min(1, irisSamples / 20);
      p.scale = 1 + (measured - 1) * w;
      p.source = "iris";
    } else {
      p.scale = 1;
      p.source = "default";
    }
    p.progress = Math.min(1, irisSamples / FULL_IRIS_SAMPLES);
  }
}

/** Nose surface depth at height `y` (along the midline). */
const noseDepthAt = (profile, y) => {
  const { noseY, noseZ } = profile;
  const n = noseY.length;
  if (y >= noseY[0]) return noseZ[0];
  for (let k = 1; k < n; k++) {
    if (y >= noseY[k]) {
      const t = (y - noseY[k]) / Math.max(noseY[k - 1] - noseY[k], 1e-4);
      return noseZ[k] + (noseZ[k - 1] - noseZ[k]) * t;
    }
  }
  return noseZ[n - 1];
};

/* ------------------------------------------------------------------ */
/*  Glasses model: normalisation, analysis, temple shader              */
/* ------------------------------------------------------------------ */
//
// "Fit space": +X = wearer's left, +Y = up, +Z = forward (away from the face),
// origin = centre of the frame front at the back surface of the rims.

const VERT_PARS = /* glsl */ `
uniform float uTryonBendOn;
uniform mat4 uTryonNorm;
uniform mat4 uTryonNormInv;
uniform float uTryonHingeZ;
uniform vec2 uTryonEarZ;
uniform vec2 uTryonDX;
uniform vec2 uTryonDY;
uniform vec2 uTryonZScale;
uniform vec3 uTryonLat;
varying float vTryonTemple;
varying float vTryonBehind;
`;

// Swings the temples at the hinge so they meet the ears, keeping them straight
// like a real rigid arm: the temple is lengthened/shortened so its modelled ear
// bend lands just behind the ear root, then an offset growing linearly from 0 at
// the hinge to full at the ear spreads/drops it onto the ear.
const VERT_MAIN = /* glsl */ `
vTryonBehind = -1.0;
{
  vec3 tryonP = (uTryonNorm * vec4(transformed, 1.0)).xyz;
  float tryonLat = smoothstep(uTryonLat.x, uTryonLat.y, abs(tryonP.x));
  vTryonTemple = tryonLat * clamp((uTryonHingeZ - tryonP.z) / uTryonLat.z, 0.0, 1.0);
  if (uTryonBendOn > 0.5) {
    float tryonSide = step(0.0, tryonP.x);
    float tryonScaleZ = mix(uTryonZScale.y, uTryonZScale.x, tryonSide);
    tryonP.z -= max(uTryonHingeZ - tryonP.z, 0.0) * (tryonScaleZ - 1.0) * tryonLat;
    float tryonEar = mix(uTryonEarZ.y, uTryonEarZ.x, tryonSide);
    float tryonT = clamp((uTryonHingeZ - tryonP.z) / max(uTryonHingeZ - tryonEar, 1e-5), 0.0, 1.0);
    float tryonW = tryonT * tryonLat;
    tryonP.x += sign(tryonP.x) * mix(uTryonDX.y, uTryonDX.x, tryonSide) * tryonW;
    tryonP.y += mix(uTryonDY.y, uTryonDY.x, tryonSide) * tryonW;
    vTryonBehind = tryonEar - tryonP.z;
    transformed = (uTryonNormInv * vec4(tryonP, 1.0)).xyz;
  }
}
`;

const FRAG_PARS = /* glsl */ `
uniform float uTryonCut;
varying float vTryonTemple;
varying float vTryonBehind;
`;

// The temple ends where it goes behind the ear (hidden there in reality).
const FRAG_MAIN = /* glsl */ `
if (vTryonTemple > 0.5 && vTryonBehind > uTryonCut) discard;
`;

const PROGRAM_KEY = "vto-glasses-v1";

const createUniforms = () => ({
  uTryonBendOn: { value: 0 },
  uTryonNorm: { value: new THREE.Matrix4() },
  uTryonNormInv: { value: new THREE.Matrix4() },
  uTryonHingeZ: { value: 0 },
  uTryonEarZ: { value: new THREE.Vector2(-1, -1) }, // x: left temple (+X), y: right (−X)
  uTryonDX: { value: new THREE.Vector2() },
  uTryonDY: { value: new THREE.Vector2() },
  uTryonZScale: { value: new THREE.Vector2(1, 1) },
  uTryonCut: { value: 1e6 },
  uTryonLat: { value: new THREE.Vector3(0.5, 0.7, 0.01) },
});

const patchMaterial = (material, uniforms) => {
  material.onBeforeCompile = (shader) => {
    Object.assign(shader.uniforms, uniforms);
    shader.vertexShader = shader.vertexShader
      .replace("#include <common>", `#include <common>\n${VERT_PARS}`)
      .replace("#include <begin_vertex>", `#include <begin_vertex>\n${VERT_MAIN}`);
    shader.fragmentShader = shader.fragmentShader
      .replace("#include <common>", `#include <common>\n${FRAG_PARS}`)
      .replace(
        "#include <clipping_planes_fragment>",
        `#include <clipping_planes_fragment>\n${FRAG_MAIN}`,
      );
  };
  material.customProgramCacheKey = () => PROGRAM_KEY;
  material.needsUpdate = true;
};

const LENS_NAME = /lens|glass(?!es)|verre|lente|linse|vidrio|cristal/i;
const IGNORE_NAME = /\b(floor|ground|shadow_?plane|shadow_?catcher|backdrop|background)\b/i;
const METAL_NAME = /(chrom|hrom|metal|steel|gold|silver|titan|brass|alumin)/i;
// Studio-lit glTF lenses reflect far too strongly in AR (milky lenses).
const LENS_REFLECTION_SCALE = 0.4;
const TEMPLE_SLICES = 40;

// Sketchfab/FBX exports often lose metalness: restore it on "chrome"/"metal" parts.
const restoreMetal = (m) => {
  if (!m.isMeshStandardMaterial || m.metalness !== 0 || m.metalnessMap || !METAL_NAME.test(m.name)) return;
  m.metalness = 0.9;
  m.roughness = Math.min(m.roughness, 0.35);
};

const materialsOf = (mesh) => (Array.isArray(mesh.material) ? mesh.material : [mesh.material]);

const isLensMaterial = (mesh, m) =>
  LENS_NAME.test(`${mesh.name} ${m.name}`) ||
  (m.transparent && m.opacity < 0.98) ||
  (m.isMeshPhysicalMaterial === true && m.transmission > 0);

const flipWinding = (geo) => {
  if (!geo.index) {
    const count = geo.attributes.position.count;
    const idx = new (count > 65535 ? Uint32Array : Uint16Array)(count);
    for (let i = 0; i < count; i++) idx[i] = i;
    geo.setIndex(new THREE.BufferAttribute(idx, 1));
  }
  const index = geo.index;
  for (let i = 0; i + 2 < index.count; i += 3) {
    const b = index.getX(i + 1);
    index.setX(i + 1, index.getX(i + 2));
    index.setX(i + 2, b);
  }
  index.needsUpdate = true;
};

// Copies every mesh with its world transform baked into the geometry.
const bakeMeshes = (source) => {
  source.updateMatrixWorld(true);
  const out = [];
  const m = new THREE.Matrix4();
  const push = (mesh, world) => {
    const geo = mesh.geometry.clone();
    geo.morphAttributes = {};
    geo.applyMatrix4(world);
    if (world.determinant() < 0) flipWinding(geo);
    const baked = new THREE.Mesh(geo, mesh.material);
    baked.name = mesh.name;
    baked.renderOrder = mesh.renderOrder;
    baked.visible = mesh.visible && !IGNORE_NAME.test(mesh.name);
    out.push(baked);
  };
  source.traverse((o) => {
    if (!o.isMesh || !o.geometry?.attributes.position) return;
    if (o.isInstancedMesh) {
      for (let i = 0; i < Math.min(o.count, 64); i++) {
        o.getMatrixAt(i, m);
        push(o, m.premultiply(o.matrixWorld));
      }
    } else {
      push(o, o.matrixWorld);
    }
  });
  return out;
};

const collectSamples = (meshes, maxPoints = 60000) => {
  let total = 0;
  for (const mesh of meshes) if (mesh.visible) total += mesh.geometry.attributes.position.count;
  const stride = Math.max(1, Math.ceil(total / maxPoints));
  const out = new Float32Array(Math.ceil(total / stride) * 3 + 3);
  let n = 0;
  let k = 0;
  for (const mesh of meshes) {
    if (!mesh.visible) continue;
    const pos = mesh.geometry.attributes.position;
    for (let i = 0; i < pos.count; i++, k++) {
      if (k % stride !== 0) continue;
      out[n++] = pos.getX(i);
      out[n++] = pos.getY(i);
      out[n++] = pos.getZ(i);
    }
  }
  return out.subarray(0, n);
};

const percentileRange = (values, trim) => {
  if (values.length === 0) return { min: 0, max: 0 };
  const s = Float32Array.from(values).sort();
  const lo = Math.floor(trim * (s.length - 1));
  const hi = Math.ceil((1 - trim) * (s.length - 1));
  return { min: s[lo], max: s[hi] };
};

const axisValues = (pts, axis) => {
  const n = pts.length / 3;
  const out = new Float32Array(n);
  for (let i = 0; i < n; i++) out[i] = pts[i * 3 + axis];
  return out;
};

// 0 = perfectly mirror-symmetric distribution along `axis`.
const asymmetry = (pts, axis, r) => {
  const B = 32;
  const h = new Float64Array(B);
  const ext = r.max - r.min || 1;
  const n = pts.length / 3;
  for (let i = 0; i < n; i++) {
    const b = Math.floor(((pts[i * 3 + axis] - r.min) / ext) * B);
    if (b >= 0 && b < B) h[b]++;
  }
  let d = 0;
  let tot = 0;
  for (let i = 0; i < B; i++) tot += h[i];
  for (let i = 0; i < B / 2; i++) d += Math.abs(h[i] - h[B - 1 - i]);
  return d / Math.max(tot, 1);
};

/**
 * Finds width / height / depth axes and which way is front and up.
 * Width: the most mirror-symmetric long axis. Front: the end with geometry
 * near the centre plane (bridge). Up: temples leave above the frame centre
 * and their tips curl downward.
 */
const detectOrientation = (pts) => {
  const n = pts.length / 3;
  const ranges = [0, 1, 2].map((a) => percentileRange(axisValues(pts, a), 0.002));
  const ext = ranges.map((r) => r.max - r.min);
  const order = [0, 1, 2].sort((a, b) => ext[b] - ext[a]);
  const hasTemples = ext[order[1]] > 0.55 * ext[order[0]];

  let lat;
  let dep;
  let up;
  if (hasTemples) {
    const s0 = asymmetry(pts, order[0], ranges[order[0]]);
    const s1 = asymmetry(pts, order[1], ranges[order[1]]);
    [lat, dep] = s0 <= s1 ? [order[0], order[1]] : [order[1], order[0]];
    up = order[2];
  } else {
    [lat, up, dep] = order;
  }

  let frontSign = 1;
  let upSign = 1;
  if (hasTemples) {
    const cLat = (ranges[lat].min + ranges[lat].max) / 2;
    const halfLat = ext[lat] / 2;
    let hi = 0;
    let lo = 0;
    for (let i = 0; i < n; i++) {
      if (Math.abs(pts[i * 3 + lat] - cLat) > 0.2 * halfLat) continue;
      const t = (pts[i * 3 + dep] - ranges[dep].min) / (ext[dep] || 1);
      if (t > 0.75) hi++;
      else if (t < 0.25) lo++;
    }
    frontSign = hi >= lo ? 1 : -1;

    let fMin = Infinity;
    let fMax = -Infinity;
    let midSum = 0;
    let midN = 0;
    let tipSum = 0;
    let tipN = 0;
    for (let i = 0; i < n; i++) {
      const d = pts[i * 3 + dep];
      const s =
        frontSign > 0
          ? (ranges[dep].max - d) / (ext[dep] || 1)
          : (d - ranges[dep].min) / (ext[dep] || 1);
      const h = pts[i * 3 + up];
      if (s < 0.12) {
        fMin = Math.min(fMin, h);
        fMax = Math.max(fMax, h);
      } else if (s > 0.3 && s < 0.6) {
        midSum += h;
        midN++;
      } else if (s > 0.88) {
        tipSum += h;
        tipN++;
      }
    }
    if (midN > 0 && fMax >= fMin) {
      const mid = midSum / midN;
      let score = mid - (fMin + fMax) / 2;
      if (tipN > 0) score += mid - tipSum / tipN;
      upSign = score >= 0 ? 1 : -1;
    }
  }

  const axis = (a, s) => new THREE.Vector3().setComponent(a, s);
  const X = axis(lat, 1);
  const Y = axis(up, upSign);
  const Z = axis(dep, frontSign);
  if (X.clone().cross(Y).dot(Z) < 0) X.negate();
  return new THREE.Matrix4().set(X.x, X.y, X.z, 0, Y.x, Y.y, Y.z, 0, Z.x, Z.y, Z.z, 0, 0, 0, 0, 1);
};

const buildTempleProfile = (pts, cx, cy, backPlane, halfW, hingeZ, minZ) => {
  const S = TEMPLE_SLICES;
  const temple = {
    slices: S,
    inner: [new Float32Array(S).fill(Infinity), new Float32Array(S).fill(Infinity)],
    minY: [new Float32Array(S).fill(Infinity), new Float32Array(S).fill(Infinity)],
    maxY: [new Float32Array(S).fill(-Infinity), new Float32Array(S).fill(-Infinity)],
    count: [new Uint32Array(S), new Uint32Array(S)],
  };
  const span = hingeZ - minZ;
  if (span <= 1e-6) return temple;
  const n = pts.length / 3;
  for (let i = 0; i < n; i++) {
    const x = pts[i * 3] - cx;
    const z = pts[i * 3 + 2] - backPlane;
    if (z >= hingeZ || Math.abs(x) < 0.55 * halfW) continue;
    const side = x >= 0 ? 0 : 1;
    const k = Math.min(S - 1, Math.max(0, Math.floor(((hingeZ - z) / span) * S)));
    const y = pts[i * 3 + 1] - cy;
    temple.inner[side][k] = Math.min(temple.inner[side][k], Math.abs(x));
    temple.minY[side][k] = Math.min(temple.minY[side][k], y);
    temple.maxY[side][k] = Math.max(temple.maxY[side][k], y);
    temple.count[side][k]++;
  }
  return temple;
};

// Depth of the hinge hardware (dense leading slices on BOTH sides), so the
// swing point sits behind it and hinges/screws are never distorted.
const hingeHardwareDepth = (t, sliceLen, maxDepth) => {
  const counts = [];
  for (let k = 0; k < t.slices; k++) counts.push(Math.min(t.count[0][k], t.count[1][k]));
  const typical = counts
    .slice(5, Math.max(6, t.slices - 5))
    .filter((c) => c > 0)
    .sort((a, b) => a - b);
  if (typical.length === 0) return 0;
  const median = typical[typical.length >> 1];
  let k = 0;
  while (k < t.slices && counts[k] > 2.5 * median) k++;
  return Math.min(k * sliceLen, maxDepth);
};

// Where does the temple underside start dropping away (a modelled ear bend)?
// Returns that fit-space z, or null for straight temples.
const detectEarBend = (t, frontHeight, hingeZ, minZ) => {
  let bendU = 0;
  let sides = 0;
  for (const side of [0, 1]) {
    let sx = 0;
    let sy = 0;
    let sxx = 0;
    let sxy = 0;
    let n = 0;
    for (let k = 0; k < t.slices; k++) {
      const u = (k + 0.5) / t.slices;
      if (u < 0.1 || u > 0.6 || t.count[side][k] === 0) continue;
      const y = t.minY[side][k];
      sx += u;
      sy += y;
      sxx += u * u;
      sxy += u * y;
      n++;
    }
    if (n < 3) continue;
    const slope = (n * sxy - sx * sy) / Math.max(n * sxx - sx * sx, 1e-9);
    const icpt = (sy - slope * sx) / n;
    const dev = (k) => icpt + (slope * (k + 0.5)) / t.slices - t.minY[side][k];
    let maxDev = 0;
    for (let k = 0; k < t.slices; k++) {
      if ((k + 0.5) / t.slices >= 0.6 && t.count[side][k] > 0) maxDev = Math.max(maxDev, dev(k));
    }
    if (maxDev <= 0.1 * frontHeight) continue;
    for (let k = 0; k < t.slices; k++) {
      const u = (k + 0.5) / t.slices;
      if (u >= 0.35 && t.count[side][k] > 0 && dev(k) > 0.1 * maxDev) {
        bendU += u;
        sides++;
        break;
      }
    }
  }
  return sides > 0 ? hingeZ - (bendU / sides) * (hingeZ - minZ) : null;
};

/** Measures the frame in fit orientation. */
const analyzeFrame = (raw, rotation) => {
  const n = raw.length / 3;
  const e = rotation.elements;
  const pts = new Float32Array(raw.length);
  for (let i = 0; i < n; i++) {
    const x = raw[i * 3];
    const y = raw[i * 3 + 1];
    const z = raw[i * 3 + 2];
    pts[i * 3] = e[0] * x + e[4] * y + e[8] * z;
    pts[i * 3 + 1] = e[1] * x + e[5] * y + e[9] * z;
    pts[i * 3 + 2] = e[2] * x + e[6] * y + e[10] * z;
  }
  const rx = percentileRange(axisValues(pts, 0), 0.002);
  const rz = percentileRange(axisValues(pts, 2), 0.002);
  const width = rx.max - rx.min || 1;
  const depth = rz.max - rz.min;
  const frontDepth = Math.max(Math.min(depth, 0.18 * width), 1e-6);
  const zFront = rz.max - frontDepth;

  // Frame front: extents of the slab closest to the viewer.
  const fx = [];
  const fy = [];
  for (let i = 0; i < n; i++) {
    if (pts[i * 3 + 2] >= zFront) {
      fx.push(pts[i * 3]);
      fy.push(pts[i * 3 + 1]);
    }
  }
  const frx = percentileRange(Float32Array.from(fx), 0.0005);
  const fry = percentileRange(Float32Array.from(fy), 0.001);
  const cx = (frx.min + frx.max) / 2;
  const halfW = Math.max((frx.max - frx.min) / 2, 1e-6);
  const cy = (fry.min + fry.max) / 2;
  const frontH = Math.max(fry.max - fry.min, 1e-6);

  // Back surface of the rims.
  const rimZ = [];
  for (let i = 0; i < n; i++) {
    const ax = Math.abs(pts[i * 3] - cx) / halfW;
    if (pts[i * 3 + 2] >= zFront && ax > 0.3 && ax < 0.85) rimZ.push(pts[i * 3 + 2]);
  }
  const backPlane = rimZ.length > 10 ? percentileRange(Float32Array.from(rimZ), 0.1).min : zFront;

  // Bridge: geometry on the centre plane.
  let bMinY = Infinity;
  let bBackZ = Infinity;
  for (let i = 0; i < n; i++) {
    const x = pts[i * 3];
    const y = pts[i * 3 + 1];
    const z = pts[i * 3 + 2];
    if (z >= zFront && Math.abs(x - cx) < 0.035 * 2 * halfW && y > cy - 0.1 * frontH) {
      bMinY = Math.min(bMinY, y);
      bBackZ = Math.min(bBackZ, z);
    }
  }
  if (!Number.isFinite(bMinY)) {
    bMinY = cy + 0.1 * frontH;
    bBackZ = backPlane;
  }

  const origin = new THREE.Vector3(cx, cy, backPlane);
  const minZ = rz.min - backPlane;

  // Temple cross-sections; swing point just behind the hinge hardware.
  const hingeZ0 = -0.015 * 2 * halfW;
  let temple = buildTempleProfile(pts, cx, cy, backPlane, halfW, hingeZ0, minZ);
  const hingeZ =
    hingeZ0 - hingeHardwareDepth(temple, (hingeZ0 - minZ) / TEMPLE_SLICES, 0.06 * 2 * halfW);
  if (hingeZ !== hingeZ0) temple = buildTempleProfile(pts, cx, cy, backPlane, halfW, hingeZ, minZ);

  let filled = 0;
  for (let k = 0; k < TEMPLE_SLICES; k++) if (temple.count[0][k] > 0 && temple.count[1][k] > 0) filled++;
  const hasTemples = depth > 0.45 * width && filled > TEMPLE_SLICES * 0.4;

  return {
    origin,
    analysis: {
      frontWidth: 2 * halfW,
      frontHeight: frontH,
      depth,
      hasTemples,
      hingeZ,
      minZ,
      maxZ: rz.max - backPlane,
      bridgeBottomY: bMinY - cy,
      bridgeBackZ: bBackZ - backPlane,
      temple,
      earBendZ: hasTemples ? detectEarBend(temple, frontH, hingeZ, minZ) : null,
    },
  };
};

// Guesses the model's unit from the frame width (real frames: ~95–200 mm).
const guessUnits = (frontWidth) => {
  const candidates = [
    { label: "m", toCm: 100 },
    { label: "cm", toCm: 1 },
    { label: "mm", toCm: 0.1 },
    { label: "in", toCm: 2.54 },
  ];
  for (const c of candidates) {
    const mm = frontWidth * c.toCm * 10;
    if (mm >= 95 && mm <= 200) return c;
  }
  return null;
};

// Temple cross-section nearest to slice `z` (fit space) on one side.
const sampleTemple = (a, side, z, out) => {
  const t = a.temple;
  const span = a.hingeZ - a.minZ;
  if (span <= 0) return null;
  const k0 = Math.min(t.slices - 1, Math.max(0, Math.floor(((a.hingeZ - z) / span) * t.slices)));
  for (let d = 0; d < t.slices; d++) {
    for (let j = 0; j < 2; j++) {
      const k = j === 0 ? k0 - d : k0 + d;
      if (k >= 0 && k < t.slices && t.count[side][k] > 0) {
        out.inner = t.inner[side][k];
        out.minY = t.minY[side][k];
        out.maxY = t.maxY[side][k];
        return out;
      }
    }
  }
  return null;
};

class GlassesAsset {
  constructor(source) {
    this.root = new THREE.Group();
    this.root.matrixAutoUpdate = false;
    this.content = new THREE.Group();
    this.root.add(this.content);
    this.uniforms = createUniforms();
    this.lensStates = new Map();
    this.meshes = bakeMeshes(source);
    if (this.meshes.length === 0) throw new Error("The file does not contain any meshes.");

    // Hide stray huge meshes (floors, backdrops) that would ruin the measurements.
    let samples = collectSamples(this.meshes);
    const rng = [0, 1, 2].map((a) => percentileRange(axisValues(samples, a), 0.01));
    const diag = Math.hypot(...rng.map((r) => r.max - r.min));
    let hidden = false;
    for (const mesh of this.meshes) {
      mesh.geometry.computeBoundingBox();
      const size = mesh.geometry.boundingBox.getSize(new THREE.Vector3());
      if (mesh.visible && size.length() > 3 * diag) {
        mesh.visible = false;
        hidden = true;
      }
    }
    if (hidden) samples = collectSamples(this.meshes);
    if (samples.length < 30) throw new Error("The model has too little geometry to fit.");

    const patched = new Set();
    for (const mesh of this.meshes) {
      this.content.add(mesh);
      let lens = false;
      for (const m of materialsOf(mesh)) {
        const isLens = isLensMaterial(mesh, m);
        if (isLens) {
          lens = true;
          if (!this.lensStates.has(m)) {
            this.lensStates.set(m, {
              transmission: m.isMeshPhysicalMaterial ? m.transmission : 0,
              opacity: m.opacity,
              transparent: m.transparent,
              depthWrite: m.depthWrite,
            });
            if ("envMapIntensity" in m) m.envMapIntensity *= LENS_REFLECTION_SCALE;
          }
        }
        if (!patched.has(m)) {
          if (!isLens) restoreMetal(m);
          patchMaterial(m, this.uniforms);
          patched.add(m);
        }
      }
      if (lens) mesh.renderOrder = Math.max(mesh.renderOrder, 2);
    }

    const rotation = detectOrientation(samples);
    const { analysis, origin } = analyzeFrame(samples, rotation);
    this.analysis = analysis;
    this.units = guessUnits(analysis.frontWidth);
    const norm = new THREE.Matrix4()
      .makeTranslation(-origin.x, -origin.y, -origin.z)
      .multiply(rotation);
    this.root.matrix.copy(norm);
    this.uniforms.uTryonNorm.value.copy(norm);
    this.uniforms.uTryonNormInv.value.copy(norm).invert();
    this.uniforms.uTryonHingeZ.value = analysis.hingeZ;
    const halfW = analysis.frontWidth / 2;
    this.uniforms.uTryonLat.value.set(0.55 * halfW, 0.75 * halfW, 0.08 * halfW);
  }

  // "alpha" turns refractive (transmission) lenses into cheap alpha-blended ones.
  setLensMode(mode) {
    for (const [m, s] of this.lensStates) {
      if (s.transmission <= 0) continue;
      if (mode === "alpha") {
        m.transmission = 0;
        m.transparent = true;
        m.opacity = Math.min(s.opacity, 0.2 + 0.5 * (1 - s.transmission));
        m.depthWrite = false;
      } else {
        m.transmission = s.transmission;
        m.transparent = s.transparent;
        m.opacity = s.opacity;
        m.depthWrite = s.depthWrite;
      }
      m.needsUpdate = true;
    }
  }

  dispose() {
    const textures = new Set();
    const materials = new Set();
    for (const mesh of this.meshes) {
      mesh.geometry.dispose();
      for (const m of materialsOf(mesh)) materials.add(m);
    }
    for (const m of materials) {
      for (const value of Object.values(m)) if (value?.isTexture) textures.add(value);
      m.dispose();
    }
    for (const t of textures) t.dispose();
    this.root.removeFromParent();
  }
}

/* ------------------------------------------------------------------ */
/*  Fit solver: places the frame on THIS face                          */
/* ------------------------------------------------------------------ */

const X_AXIS = new THREE.Vector3(1, 0, 0);
const _fitPos = new THREE.Vector3();
const _fitQ = new THREE.Quaternion();
const _fitQInv = new THREE.Quaternion();
const _fitS = new THREE.Vector3();
const _fitV = new THREE.Vector3();
const _earSection = { inner: 0, minY: 0, maxY: 0 };

// Original (un-stretched) z of the temple point that ends up at `z`.
const unscaleZ = (a, z, zScale) => a.hingeZ - (a.hingeZ - z) / zScale;

/**
 * Places the frame (canonical face space, cm):
 *  - size: real frame width ÷ the user's real face scale (iris-measured);
 *  - height: pupils slightly above the lens box centre;
 *  - depth: lenses at the vertex distance, never sunk into the nose;
 *  - temples: kept straight and swung at the hinge to rest on the ears,
 *    length matched so the ear bend sits over the ear, ended behind it.
 * Returns the fit-space → canonical matrix.
 */
const solveFit = (profile, asset, fit, outMatrix) => {
  const a = asset.analysis;
  const s = profile.scale;
  const mmToCanon = 0.1 / s;

  const unitToCm = fit.frameWidthMm
    ? fit.frameWidthMm / 10 / a.frontWidth
    : (asset.units?.toCm ?? null);
  const idealCanon = IDEAL_FRAME_TO_FACE * profile.faceWidth;
  let k = fit.sizeMode === "real" && unitToCm ? unitToCm / s : idealCanon / a.frontWidth;
  k *= fit.sizeAdjust;

  _fitQ.setFromAxisAngle(X_AXIS, THREE.MathUtils.degToRad(fit.tiltDeg));

  const cx = (profile.pupilR.x + profile.pupilL.x) / 2;
  const pupilY = (profile.pupilR.y + profile.pupilL.y) / 2;
  const cy = pupilY - PUPIL_TO_FRAME_CENTER * a.frontHeight * k + fit.offsetY * mmToCanon;
  let cz = profile.eyeZ + CORNEA_OFFSET_CM + VERTEX_DISTANCE_CM;

  // Nose contact: the bridge must sit on, not inside, the nose.
  _fitV.set(0, a.bridgeBottomY, a.bridgeBackZ).multiplyScalar(k).applyQuaternion(_fitQ);
  const noseZ = noseDepthAt(profile, cy + _fitV.y);
  cz = Math.max(cz, noseZ + 0.05 - _fitV.z) + fit.offsetZ * mmToCanon;

  _fitPos.set(cx, cy, cz);
  _fitS.setScalar(k);
  outMatrix.compose(_fitPos, _fitQ, _fitS);

  const u = asset.uniforms;
  if (!a.hasTemples) {
    u.uTryonCut.value = 1e6;
    u.uTryonBendOn.value = 0;
    return;
  }
  _fitQInv.copy(_fitQ).invert();
  const spread = (fit.templeAdjust * mmToCanon) / k;
  const minEarZ = a.hingeZ - 0.1 * a.frontWidth;
  for (const side of [0, 1]) {
    // Ear rest point in the frame's own (fit) space.
    _fitV
      .copy(side === 0 ? profile.earL : profile.earR)
      .sub(_fitPos)
      .applyQuaternion(_fitQInv)
      .divideScalar(k);
    const earZ = Math.min(_fitV.z, minEarZ);
    const bendTarget = earZ - EAR_BEND_BEHIND_ROOT_CM / k;
    const zScale =
      a.earBendZ === null
        ? 1
        : clamp((a.hingeZ - bendTarget) / (a.hingeZ - a.earBendZ), Z_SCALE_MIN, Z_SCALE_MAX);

    let dx = 0;
    let dy = 0;
    if (sampleTemple(a, side, unscaleZ(a, earZ, zScale), _earSection)) {
      // Up to ~2.5 cm of swing at the ear, like opening a real hinge wider.
      dx = clamp(Math.abs(_fitV.x) - _earSection.inner + spread, -1.2 / k, 2.5 / k);
      dy = clamp(_fitV.y - _earSection.minY, -2.5 / k, 1.0 / k);
    }
    u.uTryonEarZ.value.setComponent(side, earZ);
    u.uTryonZScale.value.setComponent(side, zScale);
    u.uTryonDX.value.setComponent(side, dx);
    u.uTryonDY.value.setComponent(side, dy);
  }
  u.uTryonCut.value = TEMPLE_CUT_BEHIND_ROOT_CM / k;
  u.uTryonBendOn.value = 1;
};

/* ------------------------------------------------------------------ */
/*  Occluders: live face mesh + head proxy (depth only)                */
/* ------------------------------------------------------------------ */

const HEAD = {
  down: 1.3, // ellipsoid centre below / behind the ear rest point
  back: 0.8,
  rimInset: 0.3, // head surface inside the temple rest point
  frontGap: 0.8, // front of the proxy behind the eyes
  halfHeight: 11,
  backDepth: 9.8,
};
// Face-mesh sides (beyond the outer eye corners) only occlude on the side turned
// away from the camera; the jittery outline would otherwise cut the near temple.
const SIDE_BAND_X = 5.0;
const SIDE_AWAY_ON = -0.2;
const SIDE_AWAY_OFF = -0.15;

const splitFaceTriangles = () => {
  const lists = [[], [], []];
  for (let t = 0; t < CANONICAL_TRIANGLES.length; t += 3) {
    let cx = 0;
    for (let j = 0; j < 3; j++) cx += CANONICAL_POSITIONS[CANONICAL_TRIANGLES[t + j] * 3] / 3;
    const bucket = cx > SIDE_BAND_X ? 1 : cx < -SIDE_BAND_X ? 2 : 0;
    lists[bucket].push(CANONICAL_TRIANGLES[t], CANONICAL_TRIANGLES[t + 1], CANONICAL_TRIANGLES[t + 2]);
  }
  return lists.map((l) => Uint16Array.from(l));
};

const depthOnlyMaterial = (side) => {
  const m = new THREE.MeshBasicMaterial({ side });
  m.colorWrite = false;
  m.depthWrite = true;
  return m;
};

const debugMaterial = (color, opacity, wireframe = false) =>
  new THREE.MeshBasicMaterial({ color, transparent: true, opacity, depthWrite: false, wireframe });

class Occluders {
  constructor() {
    this.faceGroup = new THREE.Group(); // camera space
    this.headGroup = new THREE.Group(); // canonical space
    this.sideAway = [false, false];
    this.headParts = [];
    this.headDebug = [];
    this.materials = [];
    this.geometries = [];
    this.positions = new Float32Array(CANONICAL_VERTEX_COUNT * 3);

    const attr = new THREE.BufferAttribute(this.positions, 3);
    attr.setUsage(THREE.DynamicDrawUsage);
    const makeGeo = (index) => {
      const g = new THREE.BufferGeometry();
      g.setAttribute("position", attr);
      g.setIndex(new THREE.BufferAttribute(index, 1));
      this.geometries.push(g);
      return g;
    };
    const track = (mesh, order) => {
      mesh.renderOrder = order;
      mesh.frustumCulled = false;
      return mesh;
    };
    const full = makeGeo(CANONICAL_TRIANGLES);
    const [central, left, right] = splitFaceTriangles();
    const faceDepth = depthOnlyMaterial(THREE.DoubleSide);
    this.face = track(new THREE.Mesh(makeGeo(central), faceDepth), -10);
    this.faceSides = [
      track(new THREE.Mesh(makeGeo(left), faceDepth), -10),
      track(new THREE.Mesh(makeGeo(right), faceDepth), -10),
    ];
    const wire = debugMaterial(0x5ee7ff, 0.35, true);
    this.faceDebug = track(new THREE.Mesh(full, wire), 5);
    this.faceDebug.visible = DEBUG.faceMesh;
    this.faceGroup.add(this.face, ...this.faceSides, this.faceDebug);

    // Head: two half-ellipsoids (shorter in front, longer at the back).
    const front = new THREE.SphereGeometry(1, 48, 24, 0, Math.PI);
    const back = new THREE.SphereGeometry(1, 48, 24, Math.PI, Math.PI);
    this.geometries.push(front, back);
    const headDepth = depthOnlyMaterial(THREE.FrontSide);
    const headDbg = debugMaterial(0xff5c8a, 0.22);
    this.materials.push(faceDepth, wire, headDepth, headDbg);
    const make = (g) => {
      const occ = track(new THREE.Mesh(g, headDepth), -10);
      const vis = track(new THREE.Mesh(g, headDbg), 5);
      vis.visible = DEBUG.occluders;
      this.headParts.push(occ);
      this.headDebug.push(vis);
      this.headGroup.add(occ, vis);
      return occ;
    };
    this.headFront = make(front);
    this.headBack = make(back);
    this.setOcclusion(OCCLUSION);
  }

  /**
   * Live face occluder from camera-space landmarks, re-posed by `correction`
   * (raw → smoothed pose) and pushed back by `bias` cm. `facing` > 0 when the
   * head's left side faces the camera.
   */
  updateFace(camera, correction, bias, facing) {
    const e = correction.elements;
    const p = this.positions;
    for (let i = 0; i < CANONICAL_VERTEX_COUNT; i++) {
      const x = camera[i * 3];
      const y = camera[i * 3 + 1];
      const z = camera[i * 3 + 2];
      const X = e[0] * x + e[4] * y + e[8] * z + e[12];
      const Y = e[1] * x + e[5] * y + e[9] * z + e[13];
      const Z = e[2] * x + e[6] * y + e[10] * z + e[14];
      const d = Math.hypot(X, Y, Z) || 1;
      const k = (d + bias) / d;
      p[i * 3] = X * k;
      p[i * 3 + 1] = Y * k;
      p[i * 3 + 2] = Z * k;
    }
    this.face.geometry.attributes.position.needsUpdate = true;
    for (const side of [0, 1]) {
      const f = side === 0 ? facing : -facing;
      if (f < SIDE_AWAY_ON) this.sideAway[side] = true;
      else if (f > SIDE_AWAY_OFF) this.sideAway[side] = false;
      this.faceSides[side].visible = this.occlusion && this.sideAway[side];
    }
  }

  // Fits the head proxy to the measured face (canonical space).
  updateHead(profile) {
    const { earL, earR } = profile;
    const earX = (earL.x - earR.x) / 2;
    const earY = (earL.y + earR.y) / 2;
    const earZ = (earL.z + earR.z) / 2;
    const cx = (earL.x + earR.x) / 2;
    const cy = earY - HEAD.down;
    const cz = earZ - HEAD.back;
    const b = HEAD.halfHeight;
    const eyeY = (profile.pupilL.y + profile.pupilR.y) / 2;
    const frontZ = profile.eyeZ - HEAD.frontGap;
    const cf = Math.max((frontZ - cz) / Math.sqrt(Math.max(1 - ((eyeY - cy) / b) ** 2, 0.2)), 2);
    const a =
      (earX - HEAD.rimInset) /
      Math.sqrt(Math.max(1 - ((earZ - cz) / cf) ** 2 - ((earY - cy) / b) ** 2, 0.2));
    this.headFront.position.set(cx, cy, cz);
    this.headFront.scale.set(a, b, cf);
    this.headBack.position.set(cx, cy, cz);
    this.headBack.scale.set(a, b, HEAD.backDepth);
    for (let i = 0; i < this.headParts.length; i++) {
      this.headDebug[i].position.copy(this.headParts[i].position);
      this.headDebug[i].scale.copy(this.headParts[i].scale);
    }
  }

  setOcclusion(enabled) {
    this.occlusion = enabled;
    this.face.visible = enabled;
    for (const side of [0, 1]) this.faceSides[side].visible = enabled && this.sideAway[side];
    for (const m of this.headParts) m.visible = enabled;
  }

  dispose() {
    for (const g of this.geometries) g.dispose();
    for (const m of this.materials) m.dispose();
  }
}

/* ------------------------------------------------------------------ */
/*  Loaders (MediaPipe + .glb), shared across opens                    */
/* ------------------------------------------------------------------ */

const fetchWithRetry = async (url, attempts = 3) => {
  let lastError;
  for (let i = 0; i < attempts; i++) {
    try {
      const res = await fetch(url);
      if (!res.ok) throw new Error(`HTTP ${res.status} for ${url}`);
      return await res.arrayBuffer();
    } catch (err) {
      lastError = err;
      await new Promise((r) => setTimeout(r, 400 * (i + 1)));
    }
  }
  throw lastError;
};

let landmarkerPromise = null;

const getFaceLandmarker = () => {
  if (!landmarkerPromise) {
    landmarkerPromise = (async () => {
      // Download the model once (with retries), so a network hiccup never
      // pushes tracking onto the slower CPU path.
      const [fileset, modelBuffer] = await Promise.all([
        FilesetResolver.forVisionTasks(WASM_BASE_PATH),
        fetchWithRetry(MODEL_ASSET_PATH),
      ]);
      const make = (delegate) =>
        FaceLandmarker.createFromOptions(fileset, {
          baseOptions: { modelAssetBuffer: new Uint8Array(modelBuffer), delegate },
          runningMode: "VIDEO",
          numFaces: 2, // 2 only to detect "more than one face"
          minFaceDetectionConfidence: 0.5,
          minFacePresenceConfidence: 0.5,
          minTrackingConfidence: 0.5,
          outputFaceBlendshapes: false,
          outputFacialTransformationMatrixes: true, // 3D head pose
        });
      try {
        return await make("GPU");
      } catch (gpuError) {
        console.warn("Face landmarker GPU delegate unavailable, falling back to CPU.", gpuError);
        return await make("CPU");
      }
    })().catch((err) => {
      landmarkerPromise = null;
      throw err;
    });
  }
  return landmarkerPromise;
};

// Raw .glb bytes per URL; parsed fresh for every open (own materials each time).
const modelBufferCache = new Map();
let gltfLoader = null;

const getGltfLoader = () => {
  if (!gltfLoader) {
    const draco = new DRACOLoader();
    draco.setDecoderPath(DRACO_DECODER_PATH);
    gltfLoader = new GLTFLoader().setDRACOLoader(draco).setMeshoptDecoder(MeshoptDecoder);
  }
  return gltfLoader;
};

const loadGlassesAsset = async (url) => {
  if (!url) throw new Error("No 3D model URL provided");
  if (!modelBufferCache.has(url)) {
    const promise = fetch(url)
      .then((res) => {
        if (!res.ok) throw new Error(`HTTP ${res.status} for ${url}`);
        return res.arrayBuffer();
      })
      .catch((err) => {
        modelBufferCache.delete(url);
        throw err;
      });
    modelBufferCache.set(url, promise);
  }
  const buffer = await modelBufferCache.get(url);
  const base = url.slice(0, url.lastIndexOf("/") + 1);
  const gltf = await getGltfLoader().parseAsync(buffer.slice(0), base);
  return new GlassesAsset(gltf.scene);
};

/* ------------------------------------------------------------------ */
/*  3D stage: video + glasses rendered together                        */
/* ------------------------------------------------------------------ */

class TryOnStage {
  constructor(host, asset, fitParams) {
    this.host = host;
    this.asset = asset;
    this.fit = fitParams;
    this.renderer = new THREE.WebGLRenderer({ antialias: true, alpha: false, powerPreference: "high-performance" });
    this.renderer.setPixelRatio(1);
    this.renderer.outputColorSpace = THREE.SRGBColorSpace;
    this.renderer.toneMapping = THREE.NeutralToneMapping;
    this.renderer.domElement.className = "vto-canvas";
    host.appendChild(this.renderer.domElement);

    this.scene = new THREE.Scene();
    this.scene.background = new THREE.Color(0x111111);
    const pmrem = new THREE.PMREMGenerator(this.renderer);
    this.envTexture = pmrem.fromScene(new RoomEnvironment(), 0.04).texture;
    pmrem.dispose();
    this.scene.environment = this.envTexture;
    // Key light for highlights on the frame. No shadows.
    this.light = new THREE.DirectionalLight(0xffffff, 1.1);
    this.light.position.set(-0.35, 1, 0.8);
    this.scene.add(this.light);

    this.camera = new THREE.PerspectiveCamera(FOV_Y_DEG, 4 / 3, 1, 2000);
    this.faceAnchor = new THREE.Group(); // canonical face space
    this.faceAnchor.matrixAutoUpdate = false;
    this.faceAnchor.visible = false;
    this.glassesPivot = new THREE.Group();
    this.glassesPivot.matrixAutoUpdate = false;
    this.occluders = new Occluders();
    this.occluders.faceGroup.visible = false;
    this.faceAnchor.add(this.glassesPivot, this.occluders.headGroup);
    this.scene.add(this.faceAnchor, this.occluders.faceGroup);
    asset.setLensMode(LENS_MODE);
    this.glassesPivot.add(asset.root);

    this.recon = new FaceReconstruction();
    this.calibrator = new FaceCalibrator();
    this.calibrator.setManualPd(fitParams.pdMm);
    this.poseFilter = new PoseFilter(SMOOTHING_PRESETS[SMOOTHING] || SMOOTHING_PRESETS.medium);
    this.rawMatrix = new THREE.Matrix4();
    this.smoothMatrix = new THREE.Matrix4();
    this.correction = new THREE.Matrix4();
    this.headX = new THREE.Vector3();
    this.toCamera = new THREE.Vector3();
    this.videoTexture = null;
    this.video = null;
    this.width = 0;
    this.height = 0;
    this.hasPose = false;
    this.faceSeenAt = -Infinity;
    this.lightLevel = 0.75;
    this.lastLightSample = 0;
    this.lightCtx = null;
    this.applyLightLevel();
  }

  setVideo(video) {
    if (this.video === video) return;
    this.video = video;
    this.videoTexture?.dispose();
    this.videoTexture = new THREE.VideoTexture(video);
    this.videoTexture.colorSpace = THREE.SRGBColorSpace;
    this.scene.background = this.videoTexture;
  }

  setSize(width, height) {
    if (this.width === width && this.height === height) return;
    this.width = width;
    this.height = height;
    this.renderer.setSize(width, height, false);
    this.camera.aspect = width / height;
    this.camera.updateProjectionMatrix();
  }

  /** One tracked face. `snap` skips smoothing (used for the saved photo). */
  onFace(landmarks, matrixData, nowMs, snap = false) {
    const v = this.video;
    this.rawMatrix.fromArray(matrixData);
    this.recon.update(landmarks, this.rawMatrix, v.videoWidth, v.videoHeight);
    this.calibrator.addFrame(this.recon);
    if (snap) this.poseFilter.reset();
    this.poseFilter.apply(this.rawMatrix, nowMs / 1000, this.smoothMatrix);
    this.hasPose = true;
    this.faceSeenAt = nowMs;

    this.faceAnchor.matrix.copy(this.smoothMatrix);
    this.faceAnchor.matrixWorldNeedsUpdate = true;
    // Face occluder keeps the live expression but follows the smoothed pose.
    this.correction.multiplyMatrices(this.smoothMatrix, this.recon.inverse);
    this.headX.setFromMatrixColumn(this.smoothMatrix, 0).normalize();
    this.toCamera.setFromMatrixPosition(this.smoothMatrix).negate().normalize();
    this.occluders.updateFace(
      this.recon.camera,
      this.correction,
      OCCLUSION_BIAS_CM,
      this.headX.dot(this.toCamera),
    );
    const profile = this.calibrator.profile;
    this.occluders.updateHead(profile);
    solveFit(profile, this.asset, this.fit, this.glassesPivot.matrix);
    this.glassesPivot.matrixWorldNeedsUpdate = true;
    if (AUTO_LIGHT && nowMs - this.lastLightSample > 400) this.sampleLighting(nowMs);
  }

  /** Hide the glasses right away (e.g. several faces in view). */
  hideFace() {
    this.faceSeenAt = -Infinity;
  }

  render(nowMs) {
    if (!this.video) return;
    if (this.videoTexture) this.videoTexture.needsUpdate = true;
    if (nowMs - this.faceSeenAt > FACE_RESET_MS && this.hasPose) {
      // Face gone for a while: forget the measurements (someone else may step in).
      this.hasPose = false;
      this.poseFilter.reset();
      this.calibrator.reset();
      this.calibrator.setManualPd(this.fit.pdMm);
    }
    const visible = this.hasPose && nowMs - this.faceSeenAt < FACE_HOLD_MS;
    this.faceAnchor.visible = visible;
    this.occluders.faceGroup.visible = visible;
    this.renderer.render(this.scene, this.camera);
    return this.renderer.domElement;
  }

  // Matches the virtual lighting to the room: mean brightness of the face.
  sampleLighting(nowMs) {
    this.lastLightSample = nowMs;
    if (!this.lightCtx) {
      const c = document.createElement("canvas");
      c.width = c.height = 12;
      this.lightCtx = c.getContext("2d", { willReadFrequently: true });
      if (!this.lightCtx) return;
    }
    const px = this.recon.pixels;
    let x0 = Infinity;
    let y0 = Infinity;
    let x1 = -Infinity;
    let y1 = -Infinity;
    for (const i of [10, 152, 234, 454]) {
      x0 = Math.min(x0, px[i * 2]);
      x1 = Math.max(x1, px[i * 2]);
      y0 = Math.min(y0, px[i * 2 + 1]);
      y1 = Math.max(y1, px[i * 2 + 1]);
    }
    const vw = this.video.videoWidth;
    const vh = this.video.videoHeight;
    x0 = Math.max(0, x0);
    y0 = Math.max(0, y0);
    const w = Math.min(vw - x0, x1 - x0);
    const h = Math.min(vh - y0, y1 - y0);
    if (w < 8 || h < 8) return;
    this.lightCtx.drawImage(this.video, x0, y0, w, h, 0, 0, 12, 12);
    const d = this.lightCtx.getImageData(0, 0, 12, 12).data;
    let luma = 0;
    for (let i = 0; i < d.length; i += 4) luma += 0.2126 * d[i] + 0.7152 * d[i + 1] + 0.0722 * d[i + 2];
    luma /= (d.length / 4) * 255;
    const target = clamp(0.15 + 1.1 * luma, 0.35, 1.3);
    this.lightLevel += (target - this.lightLevel) * 0.35;
    this.applyLightLevel();
  }

  applyLightLevel() {
    this.scene.environmentIntensity = this.lightLevel;
    this.light.intensity = 1.1 * this.lightLevel;
  }

  dispose() {
    this.asset.dispose();
    this.occluders.dispose();
    this.videoTexture?.dispose();
    this.envTexture.dispose();
    this.renderer.dispose();
    this.renderer.domElement.remove();
  }
}

/* ------------------------------------------------------------------ */
/*  Face detection + the (small) validation                            */
/* ------------------------------------------------------------------ */

const _poseMatrix = new THREE.Matrix4();
const _posePos = new THREE.Vector3();
const _poseQuat = new THREE.Quaternion();
const _poseScale = new THREE.Vector3();
const _euler = new THREE.Euler();

/** Returns "turned" / "pitch" if the head is beyond HEAD_LIMITS, else null. */
const checkHeadPose = (matrixData) => {
  if (!HEAD_LIMITS.enabled) return null;
  _poseMatrix.fromArray(matrixData);
  _poseMatrix.decompose(_posePos, _poseQuat, _poseScale);
  _euler.setFromQuaternion(_poseQuat, "YXZ");
  const yaw = Math.abs(THREE.MathUtils.radToDeg(_euler.y));
  const pitch = Math.abs(THREE.MathUtils.radToDeg(_euler.x));
  if (yaw > HEAD_LIMITS.maxYawDeg) return "turned";
  if (pitch > HEAD_LIMITS.maxPitchDeg) return "pitch";
  return null;
};

let lastDetectTs = 0;

/**
 * One FaceLandmarker pass.
 *   { status: "none" }                            no face
 *   { status: "multiple" }                        more than one face
 *   { status: "invalid", reason, matrix, face }   1 face, capture blocked
 *   { status: "ok", matrix, face }                1 face, good to capture
 */
const detectFace = (landmarker, video) => {
  // Timestamps must be strictly increasing.
  const ts = Math.max(Math.round(performance.now()), lastDetectTs + 1);
  lastDetectTs = ts;
  const result = landmarker.detectForVideo(video, ts);
  const faces = result?.faceLandmarks || [];

  if (faces.length === 0) return { status: "none" };
  if (faces.length > 1) return { status: "multiple" };

  const face = faces[0];
  const matrix = result?.facialTransformationMatrixes?.[0]?.data ?? null;
  if (!matrix || face.length < 468) return { status: "invalid", reason: "face", matrix: null, face };

  const problem = checkHeadPose(matrix);
  if (problem) return { status: "invalid", reason: problem, matrix, face };

  return { status: "ok", matrix, face };
};

/* ------------------------------------------------------------------ */
/*  Styles (scoped via unique class prefix, injected once)             */
/* ------------------------------------------------------------------ */

